const ROUTES = [["Leaver", ["last day", "leaving", "resign", "leaver"], "People Ops + Payroll", 24], ["Dependants and life events", ["spouse", "partner", "married", "baby", "dependant"], "Benefits (Total Rewards)", 48], ["Claims", ["claim", "rejected", "pre-approval", "reimburse"], "Insurer (broker escalation)", 48], ["Payroll deduction", ["payslip", "deduction", "salary"], "Payroll", 24], ["Enrolment and eligibility", ["eligible", "enrol", "join", "switch", "add"], "Benefits (Total Rewards)", 72], ["Pension", ["pension"], "Benefits (Total Rewards)", 72], ["Admin", ["card", "address", "document"], "Benefits (Total Rewards)", 72]];
return $input.all().map(item => {
  const text = String(item.json.message || '').toLowerCase();
  let category = 'Unclassified', owner = 'Benefits (Total Rewards): manual triage', sla_hours = 72;
  for (const [c, kws, o, s] of ROUTES) {
    if (kws.some(k => text.includes(k))) { category = c; owner = o; sla_hours = s; break; }
  }
  return { json: { request_id: item.json.request_id, employee_id: item.json.employee_id, category, owner, sla_hours, message: item.json.message } };
});
